31	#define WIFEXITED(status) true
32	#define WEXITSTATUS(status) (status)
33	#define WIFSIGNALED(status) ((status) != 0)
34	#endif
35	
36	
37	namespace zvec {
38	
39	
40	static std::string data_generator_bin_;
41	const std::string collection_name_{"write_recovery_test"};
42	const std::string dir_path_{"write_recovery_test_db"};
43	const zvec::CollectionOptions options_{false, true, 256 * 1024};
44	
45	
46	static std::string LocateDataGenerator() {
47	  return LocateBinary("data_generator");
48	}
49	
50	
51	/**
52	 * Internal helper to execute the data generator process.
53	 * If 'kill_after_seconds' is greater than 0, the process will be forcibly
54	 * terminated after the specified duration to simulate a crash.
55	 */
56	void ExecuteProcess(const std::string &start, const std::string &end,
57	                    const std::string &op, const std::string &version,
58	                    int kill_after_seconds = -1) {
59	  bool should_crash = kill_after_seconds >= 0;
60	
61	#ifdef _WIN32
62	  // 1. Build the command line string with quotes to handle paths with spaces
63	  std::string cmd_str = data_generator_bin_ + " --path " + dir_path_ +
64	                        " --start " + start + " --end " + end + " --op " + op +
65	                        " --version " + version;
66	
67	  STARTUPINFOA si = {sizeof(si)};
68	  PROCESS_INFORMATION pi;
69	
70	  std::cout << cmd_str << std::endl;
71	
72	  std::vector<char> cmd_buf(cmd_str.begin(), cmd_str.end());
73	  cmd_buf.push_back('\0');
74	  if (!CreateProcessA(NULL, cmd_buf.data(), NULL, NULL, FALSE, 0, NULL, NULL,
75	                      &si, &pi)) {
76	    FAIL() << "CreateProcess failed (" << GetLastError() << ")";
77	  }
78	
79	  if (should_crash) {
80	    std::this_thread::sleep_for(std::chrono::seconds(kill_after_seconds));
81	    // Simulate a crash by killing the process
82	    TerminateProcess(pi.hProcess, 1);
83	  }
84	
85	  WaitForSingleObject(pi.hProcess, INFINITE);
86	
87	  DWORD exit_code;
88	  GetExitCodeProcess(pi.hProcess, &exit_code);
89	  CloseHandle(pi.hProcess);
90	  CloseHandle(pi.hThread);
91	
92	  if (should_crash) {
93	    // In crash tests, we expect the process to have been terminated
94	    ASSERT_NE(exit_code, 0) << "Process was expected to crash/terminate.";
95	  } else {
96	    ASSERT_EQ(exit_code, 0) << "Process failed with exit code: " << exit_code;
97	  }
98	
99	#else
100	  // POSIX Implementation
101	  pid_t pid = fork();
102	  ASSERT_GE(pid, 0);
103	
104	  if (pid == 0) {  // Child process
105	    // Use a vector to manage arguments cleanly
106	    std::vector<const char *> args = {data_generator_bin_.c_str(),
107	                                      "--path",
108	                                      dir_path_.c_str(),
109	                                      "--start",
110	                                      start.c_str(),
111	                                      "--end",
112	                                      end.c_str(),
113	                                      "--op",
114	                                      op.c_str(),
115	                                      "--version",
116	                                      version.c_str(),
117	                                      nullptr};
118	    execvp(args[0], const_cast<char *const *>(args.data()));
119	    perror("execvp failed");
120	    _exit(1);
121	  }
122	
123	  int status;
124	  if (should_crash) {
125	    std::this_thread::sleep_for(std::chrono::seconds(kill_after_seconds));
126	    kill(pid, SIGKILL);
127	    waitpid(pid, &status, 0);
128	    ASSERT_TRUE(WIFSIGNALED(status)) << "Process did not crash as expected.";
129	  } else {
130	    waitpid(pid, &status, 0);
131	    ASSERT_TRUE(WIFEXITED(status)) << "Process exited abnormally.";
132	    ASSERT_EQ(WEXITSTATUS(status), 0);
133	  }
134	#endif
135	}
