151	class CrashRecoveryTest : public ::testing::Test {
152	 protected:
153	  void SetUp() override {
154	    zvec::test_util::RemoveTestPath("./write_recovery_test_db");
155	    ASSERT_NO_THROW(data_generator_bin_ = LocateDataGenerator());
156	  }
