164	TEST_F(CrashRecoveryTest, BasicInsertAndReopen) {
165	  {
166	    auto schema = CreateTestSchema(collection_name_);
167	    auto result = Collection::CreateAndOpen(dir_path_, *schema, options_);
168	    ASSERT_TRUE(result.has_value()) << result.error().message();
169	    auto collection = result.value();
170	    collection.reset();
171	  }
172	
173	  RunGenerator("0", "5000", "insert", "0");
174	  auto result = Collection::Open(dir_path_, options_);
175	  ASSERT_TRUE(result.has_value());
176	  auto collection = result.value();
177	  ASSERT_EQ(collection->Stats().value().doc_count, 5000)
178	      << "Document count mismatch";
179	}
180	
