182	TEST_F(CrashRecoveryTest, CrashRecoveryDuringInsertion) {
183	  {
184	    auto schema = CreateTestSchema(collection_name_);
185	    auto result = Collection::CreateAndOpen(dir_path_, *schema, options_);
186	    ASSERT_TRUE(result.has_value()) << result.error().message();
187	    auto collection = result.value();
188	    collection.reset();
189	  }
190	
191	  RunGeneratorAndCrash("0", "10000", "insert", "0", 3);
192	
193	  auto result = Collection::Open(dir_path_, options_);
194	  ASSERT_TRUE(result.has_value()) << "Failed to reopen collection after crash. "
195	                                     "Recovery mechanism may be broken.";
196	  auto collection = result.value();
197	  uint64_t doc_count{collection->Stats().value().doc_count};
198	  ASSERT_GT(doc_count, 800)
199	      << "Document count is too low after 3s of insertion and recovery";
200	
201	  for (uint64_t doc_id = 0; doc_id < doc_count; doc_id++) {
202	    const auto expected_doc = CreateTestDoc(doc_id, 0);
203	    std::vector<std::string> pks{};
204	    pks.emplace_back(expected_doc.pk());
205	    if (auto res = collection->Fetch(pks); res) {
206	      auto map = res.value();
207	      if (map.find(expected_doc.pk()) == map.end()) {
208	        FAIL() << "Returned map does not contain doc[" << expected_doc.pk()
209	               << "]";
210	      }
211	      const auto actual_doc = map.at(expected_doc.pk());
212	      ASSERT_EQ(*actual_doc, expected_doc)
213	          << "Data mismatch for doc[" << expected_doc.pk() << "]";
214	    } else {
215	      FAIL() << "Failed to fetch doc[" << expected_doc.pk() << "]";
216	    }
217	  }
218	}
